def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    pairs = []
    # A matching pair on a border marks the inward ray's starting cell.
    for c in range(w - 1):
        if grid[0][c] == grid[0][c + 1] != bg:
            pairs.append((0, c, 1, 0))
        if grid[h - 1][c] == grid[h - 1][c + 1] != bg:
            pairs.append((h - 1, c, -1, 0))
    for r in range(h - 1):
        if grid[r][0] == grid[r + 1][0] != bg:
            pairs.append((r, 0, 0, 1))
        if grid[r][w - 1] == grid[r + 1][w - 1] != bg:
            pairs.append((r, w - 1, 0, -1))

    pair_cells = set()
    for r, c, dr, dc in pairs:
        pair_cells.add((r, c))
        pair_cells.add((r - dc, c + dr))  # adjacent partner along the edge

    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in pair_cells]
    if not markers:
        return out
    mr, mc = markers[0]
    color = grid[mr][mc]
    out[mr][mc] = 4

    for r, c, dr, dc in pairs:
        # Continue the ray along the inward perpendicular direction.
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            if (rr, cc) == (mr, mc):
                break
            if (rr, cc) not in pair_cells:
                out[rr][cc] = color
            rr += dr
            cc += dc
    return out
